def run(root):
    guard=NoPhysics();sys.meta_path.insert(0,guard);d=root/'stage480';p=read(d/'plan.json')
    for group in ('sources','protected','original408_preserve'):
        for f,h in p[group].items():assert sha(f)==h,f
    assert sha(p['ledger_path'])==p['ledger_sha256']
