    assert out['alternatives'][0]['counts']['worlds']==1516
    assert out['alternatives'][1]['counts']['charged_ticks']==6040
    assert out['alternatives'][1]['counts']['worlds']==1012
    assert out['selected']['counts']['charged_ticks']==4840 and out['selected']['counts']['worlds']==812
    assert out['selected']['counts']['allocator_calls_max']==402
    assert not guard.attempts
    put(d/'contract-private.json',out);put(G/'retry/online480_contract.json',out)
    for group in ('sources','protected','original408_preserve'):
        for f,h in p[group].items():assert sha(f)==h,f
    records=[]
    for f in sorted(d.iterdir()):
        if not f.is_file():continue
        data=f.read_bytes();json.loads(data);again=f.read_bytes();assert data==again
        records.append(dict(path=str(f),bytes=len(data),sha256=hashlib.sha256(data).hexdigest(),full_readbacks=2))
    assert sum(x['bytes'] for x in records)<=p['raw_hard_bytes']
    put(root/'stage480-retention-manifest-private.json',dict(stage=480,files=records,new_archive=False,workspace_new_raw_copy=False))
    cpu=time.process_time();wall=time.perf_counter()-START;assert cpu<30 and wall<60
    result=dict(stage=480,status='ONE_ONLINE_WHOLE_COMPARISON_DESIGNED_NOT_EXECUTED',selected='B200',counts=out['selected']['counts'],storage=out['selected']['storage'],CPU_s=cpu,wall_s=wall,import_guard_attempts=guard.attempts,new_physics=0,new_world=0,new_positive_ticks=0,new_native=0,new_reset=0,new_search=0,protected18_ledger_verified=True,raw_files=len(records),raw_bytes=sum(x['bytes'] for x in records),contract_sha256=sha(G/'retry/online480_contract.json'),deadline_KST=out['deadline_KST'])
    put(G/'retry/online480_result.json',result);put(root/'stage480-checkpoint-private.json',result)
    print(json.dumps(result))

